s = p.read_text(encoding='utf-8-sig')

def replace(old, new):
    global s
    assert s.count(old) == 1, (s.count(old), old[:100])
    s = s.replace(old, new)

def field(n, name, text, append=False):
    global s
    pattern = rf'(^## Phase {n} — .*?\n### {re.escape(name)}\n)(.*?)(?=\n### |\n## )'
    m = re.search(pattern, s, re.S | re.M)
    assert m, (n, name)
    body = m[2].rstrip() + '\n\n' + text if append else text
    s = s[:m.start(2)] + body.rstrip() + '\n' + s[m.end(2):]

